import pandas as pd
import numpy as np
import json

# Load data for final stats
df = pd.read_csv('benchmark/data.csv')
df['recorded_at'] = pd.to_datetime(df['recorded_at'], utc=True)
df['source_updated_at'] = pd.to_datetime(df['source_updated_at'], utc=True)
df['update_lag_hours'] = (df['recorded_at'] - df['source_updated_at']).dt.total_seconds() / 3600
df['price_valid'] = (df['price_pence'] > 50) & (df['price_pence'] < 500)
df['lag_valid'] = df['update_lag_hours'] >= 0

# Load charts
with open('/app/output/charts.json', 'r') as f:
    charts = json.load(f)

# ============================================
# COMPUTE ALL STATISTICS
# ============================================

# Overview
total_records = len(df)
unique_stations = df['node_id'].nunique()
fuel_types = sorted(df['fuel_type'].unique().tolist())
main_fuels = ['E10', 'B7_STANDARD', 'E5', 'B7_PREMIUM']
date_range_recorded = f"{df['recorded_at'].min().strftime('%d %B %Y')} – {df['recorded_at'].max().strftime('%d %B %Y')}"
date_range_source = f"{df['source_updated_at'].min().strftime('%d %B %Y')} – {df['source_updated_at'].max().strftime('%d %B %Y')}"

# Price stats by fuel type (valid prices)
price_stats = {}
for ft in fuel_types:
    subset = df[(df['fuel_type'] == ft) & df['price_valid']]['price_pence']
    if len(subset) > 0:
        price_stats[ft] = {
            'count': len(subset),
            'mean': round(subset.mean(), 2),
            'median': round(subset.median(), 2),
            'std': round(subset.std(), 2),
            'min': round(subset.min(), 2),
            'max': round(subset.max(), 2),
            'q1': round(subset.quantile(0.25), 2),
            'q3': round(subset.quantile(0.75), 2),
            'iqr': round(subset.quantile(0.75) - subset.quantile(0.25), 2),
            'range': round(subset.max() - subset.min(), 2)
        }

# Update lag stats
valid_lags = df[df['lag_valid']]['update_lag_hours']
median_lag = round(valid_lags.median(), 3)
mean_lag = round(valid_lags.mean(), 2)
stale_24h = int((valid_lags > 24).sum())
stale_7d = int((valid_lags > 168).sum())
stale_24h_pct = round(stale_24h / len(df) * 100, 1)
stale_7d_pct = round(stale_7d / len(df) * 100, 1)

# Station-level lag stats
station_lag = df[df['lag_valid']].groupby('node_id')['update_lag_hours'].agg(['median', 'max']).reset_index()
stations_median_over_1h = int((station_lag['median'] > 1).sum())
stations_median_over_24h = int((station_lag['median'] > 24).sum())
stations_max_over_7d = int((station_lag['max'] > 168).sum())

# Station coverage
station_fuels = df.groupby('node_id')['fuel_type'].nunique().reset_index()
station_fuels.columns = ['node_id', 'fuel_type_count']
avg_fuels_per_station = round(station_fuels['fuel_type_count'].mean(), 2)
max_fuels_per_station = int(station_fuels['fuel_type_count'].max())

fuel_coverage = df.groupby('fuel_type')['node_id'].nunique().reset_index()
fuel_coverage.columns = ['fuel_type', 'station_count']
fuel_coverage = fuel_coverage.sort_values('station_count', ascending=False)

# Data quality
invalid_prices = int((~df['price_valid']).sum())
negative_lags = int((~df['lag_valid']).sum())

# Price ordering
fuel_price_order = sorted(price_stats.items(), key=lambda x: x[1]['median'])

cheap_fuel = fuel_price_order[0][0]
expensive_fuel = fuel_price_order[-1][0]

# Most/least competitive (by IQR - smaller = more competitive)
competitive_order = sorted(price_stats.items(), key=lambda x: x[1]['iqr'])
most_competitive = competitive_order[0][0]
least_competitive = competitive_order[-1][0]

# Fuel type labels
fuel_labels = {
    'E10': 'E10 (Standard Unleaded)',
    'B7_STANDARD': 'B7 Standard Diesel',
    'E5': 'E5 (Super Unleaded)',
    'B7_PREMIUM': 'B7 Premium Diesel',
    'HVO': 'HVO',
    'B10': 'B10'
}

